DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'stripe_payment_status') THEN
    CREATE TYPE "public"."stripe_payment_status" AS ENUM('PENDING', 'SUCCEEDED', 'FAILED', 'CANCELED', 'REFUNDED');
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'stripe_payment_type') THEN
    CREATE TYPE "public"."stripe_payment_type" AS ENUM('DEPOSIT', 'WITHDRAWAL');
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS "stripe_payments" (
  "id" serial PRIMARY KEY,
  "user_id" integer NOT NULL,
  "stripe_payment_intent_id" varchar(128) UNIQUE,
  "stripe_checkout_session_id" varchar(128) UNIQUE,
  "type" "stripe_payment_type" NOT NULL DEFAULT 'DEPOSIT',
  "amount_cents" integer NOT NULL,
  "currency" varchar(10) NOT NULL DEFAULT 'usd',
  "status" "stripe_payment_status" NOT NULL DEFAULT 'PENDING',
  "bank_transaction_id" bigint,
  "metadata" json,
  "created_at" timestamp DEFAULT now() NOT NULL,
  "updated_at" timestamp DEFAULT now() NOT NULL
);

